      const candidates = resultUnit === "nnc"
        ? [
          frame?.canonicalResult?.nncSlotFrame,
          frame?.nncSlotFrame,
          frame?.operationFrame?.nncSlotFrame,
        ]
        : [
          frame?.canonicalResult?.typedSlotFrame,
          frame?.typedSlotFrame,
          frame?.proofFrame?.conclusion?.finalTypedVncSlotFrame,
          frame?.canonicalResult?.proofFrame?.conclusion
            ?.finalTypedVncSlotFrame,
          frame?.resultFrame?.typedSlotFrame,
        ];
      const builder = resultUnit === "nnc"
        ? targetObject.requestClassicalNncDiagrammaticFrame
        : targetObject.requestClassicalVncDiagrammaticFrame;
      if (typeof builder !== "function") return null;
      for (const candidate of candidates.filter(Boolean)) {
        try {
          const diagram = builder(candidate);
          if (
            diagram?.authorizationStatus === "authorized"
            && Array.isArray(diagram.rows)
            && diagram.rows.length
          ) return diagram;
        } catch {
          // A nonmatching owner frame is not a diagram source.
        }
      }
      return null;
