    function buildClassicalRelationalNncParadigmCoordinateRequests(
      request = null,
      canonical = null
    ) {
      if (
        !request
        || canonical?.authorizationStatus !== "authorized"
      ) return [];
      const subjectCoordinates = [
        {
          coordinateId: "adverbialized",
          subjectMode: "adverbialized",
          subjectId: "3common"
        },
        ...["1sg", "2sg", "3common", "1pl", "2pl", "3pl"]
          .map(subjectId => ({
            coordinateId: `normal-${subjectId}`,
            subjectMode: "normal",
            subjectId
          }))
      ];
      const state = String(
        canonical.sourceFrame?.state || request.state || ""
      );
      const fixedPossessorId = String(
        canonical.sourceFrame?.stem?.fixedPossessorId || ""
      );
      const possessorIds = state === "possessive"
        ? fixedPossessorId
          ? [fixedPossessorId]
          : [
            "1sg",
            "2sg",
            "3sg",
            "1pl",
            "2pl",
            "3pl",
            "nonspecific-human",
            "nonspecific-nonhuman",
            "reciprocal"
          ]
        : [""];
      return possessorIds.flatMap(possessorId => (
        subjectCoordinates.map(subjectCoordinate => ({
          coordinateId: [
            subjectCoordinate.coordinateId,
            possessorId || "no-possessor"
          ].join(":"),
          state,
          possessorId,
          subjectMode: subjectCoordinate.subjectMode,
          subjectId: subjectCoordinate.subjectId
        }))
      ));
    }
